/**
 * @file packages/geo/src/types/index.ts
 * @description Core geographic primitives, projection types, and coordinate structures.
 */

import type { Feature, FeatureCollection, Geometry } from "geojson";

/**
 * Longitude/Latitude pair: [longitude: -180..180, latitude: -90..90]
 * Adheres strictly to the GeoJSON RFC 7946 specification (x/longitude first, y/latitude second).
 */
export type GeoCoordinate = [longitude: number, latitude: number];

/**
 * Bounding box representation: [minLongitude, minLatitude, maxLongitude, maxLatitude]
 */
export type GeoBoundingBox = [
  minLongitude: number,
  minLatitude: number,
  maxLongitude: number,
  maxLatitude: number,
];

/**
 * Visual viewport or rendering canvas dimensions
 */
export interface GeoDimensions {
  readonly width: number;
  readonly height: number;
}

/**
 * Margins / padding applied around projection bounds
 */
export interface GeoPadding {
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly left: number;
}

/**
 * Supported stable mathematical projections
 */
export type GeoProjectionType =
  | "mercator"
  | "albersUsa"
  | "equalEarth"
  | "naturalEarth1"
  | "orthographic"
  | "azimuthalEqualArea"
  | "conicEqualArea";

/**
 * Projection configuration parameters
 */
export interface GeoProjectionConfig {
  readonly type: GeoProjectionType;
  readonly center?: GeoCoordinate;
  readonly rotate?: [yaw: number, pitch: number, roll?: number];
  readonly scale?: number;
  readonly translate?: [x: number, y: number];
  readonly precision?: number;
  readonly clipAngle?: number;
  readonly parallels?: [number, number];
}

/**
 * Standard normalized feature properties structure
 */
export interface StandardFeatureProperties {
  readonly id: string;
  readonly name: string;
  readonly code?: string;
  readonly adminLevel?: number | string;
  readonly [key: string]: unknown;
}

/**
 * Normalized GeoJSON Feature with standard properties
 */
export type NormalizedGeoFeature<
  G extends Geometry = Geometry,
  P extends StandardFeatureProperties = StandardFeatureProperties,
> = Feature<G, P>;

/**
 * Normalized GeoJSON FeatureCollection
 */
export type NormalizedFeatureCollection<
  G extends Geometry = Geometry,
  P extends StandardFeatureProperties = StandardFeatureProperties,
> = FeatureCollection<G, P>;

/**
 * Diagnostic error/warning report structure
 */
export interface GeoDiagnostic {
  readonly severity: "error" | "warning" | "info";
  readonly code: string;
  readonly message: string;
  readonly path?: string;
  readonly context?: Record<string, unknown>;
}

/**
 * Result wrapper for validation and parsing operations
 */
export type GeoResult<T> =
  | {
      readonly success: true;
      readonly data: T;
      readonly diagnostics: readonly GeoDiagnostic[];
    }
  | { readonly success: false; readonly errors: readonly GeoDiagnostic[] };

/**
 * @file packages/geo/src/constants/index.ts
 * @description Geographic constants, default boundaries, and coordinate systems.
 */

import type { GeoBoundingBox, GeoDimensions, GeoPadding } from "../types";

/**
 * Standard Coordinate Reference System: WGS84 (EPSG:4326)
 */
export const STANDARD_CRS = "urn:ogc:def:crs:OGC:1.3:CRS84";

/**
 * Worldwide geographic extent in WGS84 coordinates: [minLng, minLat, maxLng, maxLat]
 */
export const WORLD_BOUNDING_BOX: GeoBoundingBox = [-180, -90, 180, 90];

/**
 * Default container dimensions for geographic previews and component frames
 */
export const DEFAULT_DIMENSIONS: GeoDimensions = {
  width: 800,
  height: 500,
};

/**
 * Default boundary inset padding in pixels
 */
export const DEFAULT_PADDING: GeoPadding = {
  top: 20,
  right: 20,
  bottom: 20,
  left: 20,
};

/**
 * Longitude limits in standard WGS84
 */
export const LONGITUDE_MIN = -180;
export const LONGITUDE_MAX = 180;

/**
 * Latitude limits in standard WGS84
 */
export const LATITUDE_MIN = -90;
export const LATITUDE_MAX = 90;

/**
 * @file packages/geo/src/geometry/index.ts
 * @description Coordinate inspection, bounding box calculation, and spatial geometry utilities.
 */

import type { GeoJsonObject, Geometry, Feature, FeatureCollection } from "geojson";
import type { GeoBoundingBox, GeoCoordinate } from "../types";
import { LATITUDE_MAX, LATITUDE_MIN, LONGITUDE_MAX, LONGITUDE_MIN } from "../constants";

/**
 * Validates whether a value conforms to a GeoCoordinate [lng, lat]
 */
export function isValidCoordinate(coord: unknown): coord is GeoCoordinate {
  if (!Array.isArray(coord) || coord.length < 2) {
    return false;
  }
  const [lng, lat] = coord;
  if (typeof lng !== "number" || typeof lat !== "number") {
    return false;
  }
  if (Number.isNaN(lng) || Number.isNaN(lat)) {
    return false;
  }
  return (
    lng >= LONGITUDE_MIN &&
    lng <= LONGITUDE_MAX &&
    lat >= LATITUDE_MIN &&
    lat <= LATITUDE_MAX
  );
}

/**
 * Validates whether a value conforms to a GeoBoundingBox [minLng, minLat, maxLng, maxLat]
 */
export function isValidBoundingBox(bbox: unknown): bbox is GeoBoundingBox {
  if (!Array.isArray(bbox) || bbox.length !== 4) {
    return false;
  }
  const [minLng, minLat, maxLng, maxLat] = bbox;
  return (
    typeof minLng === "number" &&
    typeof minLat === "number" &&
    typeof maxLng === "number" &&
    typeof maxLat === "number" &&
    !Number.isNaN(minLng) &&
    !Number.isNaN(minLat) &&
    !Number.isNaN(maxLng) &&
    !Number.isNaN(maxLat) &&
    minLng <= maxLng &&
    minLat <= maxLat &&
    minLng >= LONGITUDE_MIN &&
    maxLng <= LONGITUDE_MAX &&
    minLat >= LATITUDE_MIN &&
    maxLat <= LATITUDE_MAX
  );
}

/**
 * Recursively extracts all [lng, lat] positions from arbitrary GeoJSON coordinates
 */
function extractCoordinates(coords: unknown, target: GeoCoordinate[]): void {
  if (!Array.isArray(coords) || coords.length === 0) {
    return;
  }
  if (
    typeof coords[0] === "number" &&
    typeof coords[1] === "number" &&
    coords.length >= 2
  ) {
    target.push([coords[0], coords[1]]);
    return;
  }
  for (const item of coords) {
    extractCoordinates(item, target);
  }
}

/**
 * Extracts all coordinates from a GeoJSON geometry
 */
export function getCoordinatesFromGeometry(geometry: Geometry): GeoCoordinate[] {
  const result: GeoCoordinate[] = [];
  if (geometry.type === "GeometryCollection") {
    for (const geom of geometry.geometries) {
      result.push(...getCoordinatesFromGeometry(geom));
    }
  } else if ("coordinates" in geometry) {
    extractCoordinates(geometry.coordinates, result);
  }
  return result;
}

/**
 * Calculates the bounding box [minLng, minLat, maxLng, maxLat] for any GeoJSON object.
 * Throws a descriptive error if the object contains no valid coordinates.
 */
export function calculateBoundingBox(geojson: GeoJsonObject): GeoBoundingBox {
  const coordinates: GeoCoordinate[] = [];

  if (geojson.type === "FeatureCollection") {
    const fc = geojson as FeatureCollection;
    for (const feature of fc.features) {
      if (feature.geometry) {
        coordinates.push(...getCoordinatesFromGeometry(feature.geometry));
      }
    }
  } else if (geojson.type === "Feature") {
    const f = geojson as Feature;
    if (f.geometry) {
      coordinates.push(...getCoordinatesFromGeometry(f.geometry));
    }
  } else {
    coordinates.push(...getCoordinatesFromGeometry(geojson as Geometry));
  }

  if (coordinates.length === 0) {
    throw new Error(
      "GeoCN: Cannot calculate bounding box for empty or geometry-less GeoJSON object."
    );
  }

  let minLng = Infinity;
  let minLat = Infinity;
  let maxLng = -Infinity;
  let maxLat = -Infinity;

  for (const [lng, lat] of coordinates) {
    if (lng < minLng) minLng = lng;
    if (lat < minLat) minLat = lat;
    if (lng > maxLng) maxLng = lng;
    if (lat > maxLat) maxLat = lat;
  }

  return [minLng, minLat, maxLng, maxLat];
}

/**
 * Calculates the center coordinate [lng, lat] from a bounding box
 */
export function getBoundingBoxCenter(bbox: GeoBoundingBox): GeoCoordinate {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  return [(minLng + maxLng) / 2, (minLat + maxLat) / 2];
}

/**
 * @file packages/geo/src/projections/index.ts
 * @description Mathematical projection factories and deterministic fit-to-container utilities.
 */

import {
  geoMercator,
  geoAlbersUsa,
  geoEqualEarth,
  geoNaturalEarth1,
  geoOrthographic,
  geoAzimuthalEqualArea,
  geoConicEqualArea,
  type GeoProjection,
  type ExtendedFeatureCollection,
} from "d3-geo";
import type { GeoJsonObject } from "geojson";
import type { GeoDimensions, GeoPadding, GeoProjectionConfig } from "../types";
import { DEFAULT_DIMENSIONS, DEFAULT_PADDING } from "../constants";

/**
 * Creates a configured d3-geo projection instance based on GeoProjectionConfig
 */
export function createProjection(config: GeoProjectionConfig): GeoProjection {
  let projection: GeoProjection;

  switch (config.type) {
    case "mercator":
      projection = geoMercator();
      break;
    case "albersUsa":
      projection = geoAlbersUsa();
      break;
    case "equalEarth":
      projection = geoEqualEarth();
      break;
    case "naturalEarth1":
      projection = geoNaturalEarth1();
      break;
    case "orthographic":
      projection = geoOrthographic();
      break;
    case "azimuthalEqualArea":
      projection = geoAzimuthalEqualArea();
      break;
    case "conicEqualArea": {
      const conic = geoConicEqualArea();
      if (config.parallels) {
        conic.parallels(config.parallels);
      }
      projection = conic;
      break;
    }
    default: {
      const exhaustiveCheck: never = config.type;
      throw new Error(`GeoCN: Unsupported projection type "${String(exhaustiveCheck)}"`);
    }
  }

  if (config.center) {
    projection.center(config.center);
  }
  if (config.rotate) {
    const [yaw, pitch, roll] = config.rotate;
    if (typeof roll === "number") {
      projection.rotate([yaw, pitch, roll]);
    } else {
      projection.rotate([yaw, pitch]);
    }
  }
  if (typeof config.scale === "number") {
    projection.scale(config.scale);
  }
  if (config.translate) {
    projection.translate(config.translate);
  }
  if (typeof config.precision === "number") {
    projection.precision(config.precision);
  }
  if (typeof config.clipAngle === "number") {
    projection.clipAngle(config.clipAngle);
  }

  return projection;
}

/**
 * Fits a d3-geo projection to a GeoJSON object inside the specified dimensions with padding.
 * Ensures the geographic visualization scales deterministically within responsive containers.
 */
export function fitProjectionToContainer(
  projection: GeoProjection,
  geojson: GeoJsonObject,
  dimensions: GeoDimensions = DEFAULT_DIMENSIONS,
  padding: Partial<GeoPadding> = {}
): GeoProjection {
  const mergedPadding: GeoPadding = {
    top: padding.top ?? DEFAULT_PADDING.top,
    right: padding.right ?? DEFAULT_PADDING.right,
    bottom: padding.bottom ?? DEFAULT_PADDING.bottom,
    left: padding.left ?? DEFAULT_PADDING.left,
  };

  const extent: [[number, number], [number, number]] = [
    [mergedPadding.left, mergedPadding.top],
    [
      Math.max(1, dimensions.width - mergedPadding.right),
      Math.max(1, dimensions.height - mergedPadding.bottom),
    ],
  ];

  // d3-geo fitExtent expects an ExtendedFeatureCollection or GeoJsonObject
  projection.fitExtent(extent, geojson as unknown as ExtendedFeatureCollection);
  return projection;
}
